def apply_filters(self, table, text_filter, permission_filter=None):
    row_count = table.rowCount()
    permitted_items = range(row_count) if permission_filter is None or permission_filter == "all" else [row_num for row_num in range(row_count) if permission_filter == table.item(row_num, 1).text()]
    for row_num in range(row_count):
        if row_num in permitted_items and text_filter in table.item(row_num, 0).text():
            table.showRow(row_num)
        else:
            table.hideRow(row_num)
